/* Map page foundation */
body.vano-map-surface{--o:#D9703F;--o2:#F59A62;--bg:#07080a;--glass:rgba(10,12,15,.86);--glass2:rgba(16,18,22,.965);--line:rgba(255,255,255,.075);--text:#f7f8fa;--muted:#9198a3;--green:#55d7a0;--red:#ff666d;--blue:#7fb3ff;--ink:#0b0d10;--soft:#171a1f}
