body.vano-map-surface .planner-adjust-btn i,
body.vano-map-surface .planner-adjust-btn svg{color:#c7d0da}
body.vano-map-surface .planner-adjust-btn span{font-size:10px;font-weight:800;line-height:1;letter-spacing:-.15px}

body.vano-map-surface .planner-expand-hint{
