}
body.vano-map-surface .planner-expand-hint span{font-size:11px;font-weight:760}
body.vano-map-surface .planner-expanded{margin-top:11px}

body.vano-map-surface[data-mood="day"] .planner-heading-copy b{color:#111722}
body.vano-map-surface[data-mood="day"] .planner-heading-copy small{color:#b24f0c;background:rgba(255,106,26,.09);border-color:rgba(255,106,26,.11)}
body.vano-map-surface[data-mood="day"] .planner-weather{
