}
body.vano-map-surface[data-mood="day"] .planner-search-card .location-input{color:#0f1723}
body.vano-map-surface[data-mood="day"] .planner-search-card .location-input::placeholder{color:#717b88}
body.vano-map-surface[data-mood="day"] .planner-search-card .row-btn,
body.vano-map-surface[data-mood="day"] .planner-adjust-btn,
body.vano-map-surface[data-mood="day"] .planner-expand-hint{
