  body.vano-map-surface .planner-preset-icon{width:34px;height:34px;border-radius:12px}
  body.vano-map-surface .planner-preset b{font-size:11px}
  body.vano-map-surface .planner-preset small{font-size:9px}
  body.vano-map-surface .planner-search-row{gap:7px}
