/* Bundled map layer */
/* ============================================================
   VANO V74 — MAP UI REBUILD
   Mobile-first / tablet / desktop / White + Black
   Visual layer rebuilt from zero while preserving existing IDs,
   routing logic and event hooks.
   ============================================================ */

body.vano-map-surface{
  --vg-primary:#F59A62;
  --vg-primary-strong:#D9703F;
  --vg-primary-soft:#FFFBF2;
  --vg-primary-ring:rgba(217,112,63,.18);
  --vg-bg:#F6F7FB;
  --vg-surface:rgba(255,255,255,.96);
  --vg-surface-solid:#FFFFFF;
  --vg-surface-soft:#F7F8FC;
  --vg-surface-glass:rgba(255,255,255,.88);
  --vg-text:#161821;
  --vg-text-2:#4F5667;
  --vg-muted:#7A8190;
  --vg-border:rgba(20,24,36,.09);
  --vg-border-strong:rgba(20,24,36,.14);
  --vg-shadow:0 18px 52px rgba(28,33,51,.14);
  --vg-shadow-soft:0 8px 24px rgba(28,33,51,.09);
  --vg-success:#20B783;
  --vg-warning:#F29C38;
  --vg-danger:#E95C67;
  --vg-map-control:rgba(255,255,255,.94);
  --vg-radius-xl:28px;
  --vg-radius-lg:22px;
  --vg-radius-md:17px;
  --vg-radius-sm:13px;
  --planner-collapsed-h:176px;
  --vg-safe-top:max(12px,env(safe-area-inset-top));
  --vg-safe-bottom:max(10px,env(safe-area-inset-bottom));
}

html[data-vano-theme="black"] body.vano-map-surface{
  --vg-bg:#090A0F;
  --vg-surface:rgba(18,20,28,.97);
  --vg-surface-solid:#12141C;
  --vg-surface-soft:#191C26;
  --vg-surface-glass:rgba(16,18,25,.89);
  --vg-text:#F7F7FB;
  --vg-text-2:#C0C5D0;
  --vg-muted:#8C93A3;
  --vg-border:rgba(255,255,255,.085);
  --vg-border-strong:rgba(255,255,255,.13);
  --vg-shadow:0 22px 58px rgba(0,0,0,.42);
  --vg-shadow-soft:0 10px 28px rgba(0,0,0,.26);
  --vg-primary-soft:rgba(217,112,63,.14);
  --vg-primary-ring:rgba(245,154,98,.22);
  --vg-map-control:rgba(18,20,28,.95);
}

html body.vano-map-surface,
body.vano-map-surface{
  width:100%;height:100%;margin:0!important;padding:0!important;
  overflow:hidden!important;background:var(--vg-bg)!important;
}
body.vano-map-surface{color:var(--vg-text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important}
body.vano-map-surface *{box-sizing:border-box}
body.vano-map-surface button,
body.vano-map-surface input,
body.vano-map-surface select{font:inherit}
body.vano-map-surface button{-webkit-tap-highlight-color:transparent}

/* ----- app canvas ----- */
body.vano-map-surface .ws-app{
  position:fixed!important;inset:0!important;width:100%!important;max-width:none!important;
  height:100dvh!important;min-height:100svh!important;margin:0!important;
  overflow:hidden!important;background:var(--vg-bg)!important;box-shadow:none!important;
  isolation:isolate;
}
body.vano-map-surface #map{position:absolute!important;inset:0!important;background:#EDEFF5!important}
html[data-vano-theme="black"] body.vano-map-surface #map{background:#10121A!important}
body.vano-map-surface .map-vignette{
  z-index:2!important;pointer-events:none!important;
  background:linear-gradient(180deg,rgba(16,18,28,.09) 0,transparent 18%,transparent 72%,rgba(16,18,28,.08) 100%)!important;
}
html[data-vano-theme="black"] body.vano-map-surface .map-vignette{
  background:linear-gradient(180deg,rgba(0,0,0,.18) 0,transparent 22%,transparent 70%,rgba(0,0,0,.2) 100%)!important;
}
body.vano-map-surface .ambient-halo,
body.vano-map-surface .road-mood-hint{opacity:.35}

/* ----- top navigation ----- */
body.vano-map-surface .header.vano-map-topbar{
  position:absolute!important;z-index:32!important;top:var(--vg-safe-top)!important;
  left:12px!important;right:12px!important;height:52px!important;
  display:grid!important;grid-template-columns:48px 1fr 48px!important;align-items:center!important;
  gap:10px!important;opacity:1!important;pointer-events:auto!important;
  transition:opacity .2s ease,transform .24s ease!important;
}
body.vano-map-surface .map-top-action{
  width:48px;height:48px;border:1px solid var(--vg-border)!important;border-radius:17px!important;
  background:var(--vg-map-control)!important;color:var(--vg-text)!important;
  display:grid!important;place-items:center!important;box-shadow:var(--vg-shadow-soft)!important;
  backdrop-filter:blur(18px) saturate(145%);-webkit-backdrop-filter:blur(18px) saturate(145%);
  cursor:pointer;transition:transform .15s ease,background .18s ease,border-color .18s ease!important;
}
body.vano-map-surface .map-top-action:active{transform:scale(.95)}
body.vano-map-surface .map-top-action:focus-visible{outline:3px solid var(--vg-primary-ring);outline-offset:2px}
body.vano-map-surface .map-brand{
  justify-self:center;display:flex;align-items:center;gap:8px;height:46px;padding:0 14px 0 10px;
  border-radius:17px;border:1px solid var(--vg-border);background:var(--vg-map-control);
  color:var(--vg-text)!important;text-decoration:none!important;box-shadow:var(--vg-shadow-soft);
  backdrop-filter:blur(18px) saturate(145%);-webkit-backdrop-filter:blur(18px) saturate(145%);
}
body.vano-map-surface .map-brand-mark{width:29px;height:29px;border-radius:10px;display:grid;place-items:center;background:var(--vg-primary-soft);overflow:hidden}
body.vano-map-surface .map-brand-mark img{width:25px;height:25px;display:block;object-fit:contain}
body.vano-map-surface .map-brand-name{font-size:13px;font-weight:900;letter-spacing:.07em}
html[data-vano-theme="black"] body.vano-map-surface .map-brand-mark{background:rgba(217,112,63,.16)}
body.vano-map-surface .body-nav .header.vano-map-topbar{opacity:0!important;transform:translateY(-8px)!important;pointer-events:none!important}

/* ----- guest pill / GPS ----- */
body.vano-map-surface .guest-trial-pill{
  top:calc(var(--vg-safe-top) + 60px)!important;right:12px!important;left:auto!important;
  height:34px!important;padding:0 10px!important;border-radius:999px!important;
  border:1px solid var(--vg-border)!important;background:var(--vg-map-control)!important;
  color:var(--vg-text-2)!important;box-shadow:var(--vg-shadow-soft)!important;
}
body.vano-map-surface .status-chip{
  top:calc(var(--vg-safe-top) + 62px)!important;left:12px!important;height:34px!important;max-width:160px!important;
  padding:0 10px!important;border:1px solid var(--vg-border)!important;border-radius:999px!important;
  background:var(--vg-map-control)!important;color:var(--vg-text-2)!important;box-shadow:var(--vg-shadow-soft)!important;
  backdrop-filter:blur(16px)!important;-webkit-backdrop-filter:blur(16px)!important;
}
body.vano-map-surface .status-chip .dot{background:var(--vg-success)!important;box-shadow:0 0 0 4px rgba(32,183,131,.11)!important}
body.vano-map-surface .gps-quality{
  top:calc(var(--vg-safe-top) + 62px)!important;right:12px!important;height:34px!important;
  border-color:var(--vg-border)!important;background:var(--vg-map-control)!important;color:var(--vg-text-2)!important;
  box-shadow:var(--vg-shadow-soft)!important;
}

/* ----- map floating tools ----- */
body.vano-map-surface .map-tools{
  z-index:23!important;right:12px!important;top:calc(var(--vg-safe-top) + 110px)!important;
  gap:8px!important;
}
body.vano-map-surface .map-btn,
body.vano-map-surface .floating-locate,
body.vano-map-surface .nav-stack-btn,
body.vano-map-surface .nav-audio-toggle{
  width:46px!important;height:46px!important;border-radius:16px!important;
  border:1px solid var(--vg-border)!important;background:var(--vg-map-control)!important;
  color:var(--vg-text)!important;box-shadow:var(--vg-shadow-soft)!important;
  backdrop-filter:blur(16px) saturate(140%)!important;-webkit-backdrop-filter:blur(16px) saturate(140%)!important;
  transition:transform .14s ease,background .18s ease,color .18s ease!important;
}
body.vano-map-surface .map-btn:active,
body.vano-map-surface .floating-locate:active,
body.vano-map-surface .nav-stack-btn:active,
body.vano-map-surface .nav-audio-toggle:active{transform:scale(.94)}
body.vano-map-surface .map-btn.active,
body.vano-map-surface .map-btn.safety-open,
body.vano-map-surface .nav-stack-btn.immersive-active,
body.vano-map-surface .nav-audio-toggle.active{
  background:var(--vg-primary)!important;color:#fff!important;border-color:transparent!important;
  box-shadow:0 10px 26px rgba(217,112,63,.28)!important;
}
body.vano-map-surface .floating-locate{
  z-index:25!important;right:12px!important;left:auto!important;
  bottom:calc(var(--vg-safe-bottom) + var(--planner-collapsed-h) + 12px)!important;
  top:auto!important;
}
body.vano-map-surface .floating-preview-cancel{background:var(--vg-surface-solid)!important;color:var(--vg-text)!important;border-color:var(--vg-border)!important}

/* ----- location permission ----- */
body.vano-map-surface .permission{
  z-index:70!important;top:calc(var(--vg-safe-top) + 2px)!important;left:10px!important;right:10px!important;
  max-width:520px;margin:0 auto!important;padding:12px!important;border-radius:20px!important;
  border:1px solid var(--vg-border)!important;background:var(--vg-surface)!important;color:var(--vg-text)!important;
  box-shadow:var(--vg-shadow)!important;backdrop-filter:blur(22px)!important;-webkit-backdrop-filter:blur(22px)!important;
}
body.vano-map-surface .permission-icon{background:var(--vg-primary-soft)!important;color:var(--vg-primary)!important}
body.vano-map-surface .permission-copy b{font-size:12px!important;color:var(--vg-text)!important}
body.vano-map-surface .permission-copy span{font-size:10px!important;color:var(--vg-muted)!important}
body.vano-map-surface .permission button{background:var(--vg-primary)!important;color:#fff!important;border-radius:12px!important}

/* ============================================================
   MAIN PLANNER — MOBILE BOTTOM SHEET
   ============================================================ */
body.vano-map-surface .sheet{
  --planner-drag-y:0px;
  position:absolute!important;z-index:30!important;
  left:10px!important;right:10px!important;bottom:var(--vg-safe-bottom)!important;
  width:auto!important;max-width:620px!important;margin:0 auto!important;
  max-height:min(78dvh,720px)!important;padding:7px 14px 14px!important;
  border:1px solid var(--vg-border)!important;border-radius:30px!important;
  background:var(--vg-surface)!important;color:var(--vg-text)!important;
  box-shadow:var(--vg-shadow)!important;
  backdrop-filter:blur(30px) saturate(150%)!important;-webkit-backdrop-filter:blur(30px) saturate(150%)!important;
  overflow:hidden!important;
  transform:translateY(var(--planner-drag-y))!important;
  transition:transform .36s cubic-bezier(.22,.84,.24,1),opacity .22s ease,border-radius .22s ease!important;
}
body.vano-map-surface .sheet.sheet-dragging{transition:none!important}
body.vano-map-surface .sheet.sheet-collapsed{
  transform:translateY(calc(100% - var(--planner-collapsed-h) + var(--planner-drag-y)))!important;
}
