    flex-wrap:wrap!important;
    column-gap:3px!important;
    row-gap:0!important;
  }
  body.vano-map-surface.body-nav .ws-app .floating-speedo small{
    flex:0 0 100%!important;
    font-size:5.8px!important;
    line-height:1!important;
    letter-spacing:.07em!important;
    text-align:center!important;
  }
  body.vano-map-surface.body-nav .ws-app .floating-speedo strong{
    font-size:16px!important;
    line-height:1!important;
  }
  body.vano-map-surface.body-nav .ws-app .floating-speedo span{
    font-size:6.5px!important;
    line-height:1!important;
  }

  /* Right rail: recenter, voice, then the wider 3D/Mapa anchor. */
  body.vano-map-surface.body-nav .ws-app #navControlStack{
    position:absolute!important;
    z-index:72!important;
    left:auto!important;
    right:var(--v100-edge-right)!important;
    top:auto!important;
    bottom:var(--v100-dock-bottom)!important;
    width:var(--v100-wide)!important;
    min-width:var(--v100-wide)!important;
    max-width:var(--v100-wide)!important;
    height:auto!important;
    margin:0!important;
    display:flex!important;
    flex-direction:column!important;
    align-items:center!important;
    justify-content:flex-end!important;
    gap:7px!important;
  }

  body.vano-map-surface.body-nav .ws-app #navDrawerRecenter,
body.vano-map-surface.body-nav .ws-app #soundBtn{
    position:relative!important;
    inset:auto!important;
    width:var(--v100-round)!important;
    min-width:var(--v100-round)!important;
    max-width:var(--v100-round)!important;
    height:var(--v100-round)!important;
    min-height:var(--v100-round)!important;
    max-height:var(--v100-round)!important;
    margin:0!important;
    padding:0!important;
    border-radius:14px!important;
    flex:0 0 var(--v100-round)!important;
  }

  body.vano-map-surface.body-nav .ws-app #navCameraToggle{
    width:var(--v100-wide)!important;
    min-width:var(--v100-wide)!important;
    max-width:var(--v100-wide)!important;
    height:var(--v100-wide-h)!important;
    min-height:var(--v100-wide-h)!important;
    max-height:var(--v100-wide-h)!important;
    margin:0!important;
    padding:0 8px!important;
    border-radius:15px!important;
    flex:0 0 var(--v100-wide-h)!important;
  }

  /* Voice popover follows the right rail instead of covering the ETA bar. */
  body.vano-map-surface.body-nav .ws-app .nav-voice-popover{
    right:calc(var(--v100-edge-right) + var(--v100-wide) + 8px)!important;
    bottom:calc(var(--v100-dock-bottom) + var(--v100-wide-h) + 7px)!important;
  }
}

@media(max-width:380px){
  body.vano-map-surface.body-nav .ws-app{
    --v100-edge:max(7px, calc(env(safe-area-inset-left) + 5px));
    --v100-edge-right:max(7px, calc(env(safe-area-inset-right) + 5px));
    --v100-wide:64px;
    --v100-wide-h:42px;
    --v100-round:42px;
  }
}

/* =====================================================================
   VANO V101 — DRIVER FIRST / CLEAN MAP UI
   Front-end only. Keeps all legacy IDs/hooks alive for v100 JS while
   reducing chrome, composite effects and distraction around the map.
   ===================================================================== */
body.vano-map-surface{
  --v101-accent:#D9703F;
  --v101-accent-soft:#FFF2E8;
  --v101-ink:#15171c;
  --v101-copy:#6d7280;
  --v101-line:rgba(22,24,29,.09);
  --v101-surface:rgba(255,255,255,.985);
  --v101-shadow:0 10px 32px rgba(18,22,33,.10),0 2px 8px rgba(18,22,33,.05);
  --v101-shadow-soft:0 6px 18px rgba(18,22,33,.08);
  --v101-radius:24px;
}

body.vano-map-surface,
body.vano-map-surface button,
body.vano-map-surface input,
body.vano-map-surface select,
body.vano-map-surface textarea{
  font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text",Inter,system-ui,sans-serif!important;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}

/* Keep the map itself visually dominant. Heavy atmospheric layers caused
   extra GPU composition and made road labels harder to read. */
body.vano-map-surface .map-vignette,
body.vano-map-surface .ambient-halo,
body.vano-map-surface .road-mood-hint{display:none!important}
body.vano-map-surface .map-mood-fade{pointer-events:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important}

/* Healthy GPS is silent. Surface only actionable states elsewhere. */
body.vano-map-surface .status-chip,
body.vano-map-surface .gps-quality,
body.vano-map-surface .nav-tracking,
body.vano-map-surface .nav-immersive-chip{display:none!important}

/* Common materials: almost opaque instead of full-screen blur. */
body.vano-map-surface #planSheet,
body.vano-map-surface .options-btn,
body.vano-map-surface .map-tools .map-btn,
body.vano-map-surface .floating-locate,
body.vano-map-surface .floating-speedo,
body.vano-map-surface .nav-maneuver-top,
body.vano-map-surface .nav-street-chip,
body.vano-map-surface #activeNav,
body.vano-map-surface .nav-stack-btn,
body.vano-map-surface .nav-audio-toggle,
body.vano-map-surface .nav-drawer-toggle,
body.vano-map-surface .nav-drawer-btn,
body.vano-map-surface .traffic-radar,
body.vano-map-surface .nav-alt-hint,
body.vano-map-surface .destination-confirm{
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

body.vano-map-surface .header{z-index:55!important;top:max(12px,calc(env(safe-area-inset-top) + 8px))!important;right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;left:auto!important;width:auto!important}
body.vano-map-surface .header-actions{display:flex!important;gap:8px!important}
body.vano-map-surface .options-btn{
  width:46px!important;height:46px!important;padding:0!important;border-radius:16px!important;
  border:1px solid var(--v101-line)!important;background:var(--v101-surface)!important;color:#565c69!important;
  box-shadow:var(--v101-shadow-soft)!important;display:grid!important;place-items:center!important;
  transition:transform .14s ease,background .14s ease!important;
}
body.vano-map-surface .options-btn:active{transform:scale(.94)!important;background:#f6f6f8!important}

/* One calm safety entry on the free map. The detailed alert/report tools stay
   available inside their existing sheet, but no longer crowd the map. */
body.vano-map-surface .map-tools{top:max(68px,calc(env(safe-area-inset-top) + 64px))!important;right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;gap:0!important}
body.vano-map-surface .map-tools #quickAlertBtn,
body.vano-map-surface .map-tools #focusModeBtn{display:none!important}
body.vano-map-surface .map-tools #safetyToolsBtn{
  display:grid!important;width:46px!important;height:46px!important;border-radius:16px!important;
  background:var(--v101-surface)!important;border:1px solid var(--v101-line)!important;
  color:var(--v101-accent)!important;box-shadow:var(--v101-shadow-soft)!important;
}

/* Free-map destination planner: compact navigation search first. */
body.vano-map-surface:not(.body-nav) #planSheet{
  left:max(12px,calc(env(safe-area-inset-left) + 10px))!important;
  right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;
  bottom:max(12px,calc(env(safe-area-inset-bottom) + 8px))!important;
  padding:8px 10px 10px!important;border:1px solid var(--v101-line)!important;
  border-radius:28px!important;background:var(--v101-surface)!important;
  box-shadow:var(--v101-shadow)!important;color:var(--v101-ink)!important;
  overflow:visible!important;
  transition:height .24s cubic-bezier(.22,.8,.24,1),max-height .24s cubic-bezier(.22,.8,.24,1),transform .2s ease!important;
}
body.vano-map-surface:not(.body-nav) #planSheet .grab{
  width:36px!important;height:4px!important;margin:0 auto 7px!important;border-radius:999px!important;background:#d6d7dc!important;
}
body.vano-map-surface:not(.body-nav) #planSheet.sheet-collapsed{
  height:82px!important;max-height:82px!important;min-height:82px!important;
}
body.vano-map-surface:not(.body-nav) #planSheet.sheet-collapsed .planner-heading,
body.vano-map-surface:not(.body-nav) #planSheet.sheet-collapsed .planner-presets,
body.vano-map-surface:not(.body-nav) #planSheet.sheet-collapsed .planner-expanded{display:none!important}
body.vano-map-surface:not(.body-nav) #planSheet.sheet-collapsed .planner-search-row{margin:0!important}

body.vano-map-surface .planner-heading{margin:2px 3px 10px!important}
body.vano-map-surface .planner-heading-copy small,
body.vano-map-surface .planner-weather{display:none!important}
body.vano-map-surface .planner-heading-copy b{font-size:20px!important;letter-spacing:-.55px!important;font-weight:800!important;color:var(--v101-ink)!important}
body.vano-map-surface .planner-search-row{grid-template-columns:minmax(0,1fr) 48px!important;gap:8px!important;align-items:center!important}
body.vano-map-surface .planner-search-card.search-card{
  margin:0!important;padding:0!important;border:0!important;border-radius:20px!important;background:#f1f1f4!important;
  box-shadow:inset 0 0 0 1px rgba(22,24,29,.035)!important;overflow:visible!important;
}
body.vano-map-surface .planner-location-row.location-row{height:54px!important;min-height:54px!important;grid-template-columns:42px minmax(0,1fr) 42px!important}
body.vano-map-surface .planner-search-icon{color:#777c86!important}
body.vano-map-surface .planner-search-card .location-input{
  height:54px!important;font-size:16px!important;font-weight:650!important;letter-spacing:-.18px!important;color:var(--v101-ink)!important;
}
body.vano-map-surface .planner-search-card .location-input::placeholder{color:#8a8f99!important;font-weight:580!important}
body.vano-map-surface .voice-search-btn{
  width:36px!important;height:36px!important;margin:0 5px 0 0!important;border:0!important;border-radius:13px!important;
  background:#fff!important;color:var(--v101-accent)!important;box-shadow:0 1px 4px rgba(0,0,0,.07)!important;
}
body.vano-map-surface .planner-adjust-btn{
  width:48px!important;height:54px!important;border:0!important;border-radius:18px!important;background:#f1f1f4!important;
  color:#666c78!important;box-shadow:none!important;
}
body.vano-map-surface .planner-adjust-btn:active{transform:scale(.95)!important;background:#e9e9ed!important}
body.vano-map-surface .planner-presets{gap:8px!important;margin-top:9px!important}
body.vano-map-surface .planner-preset{
  min-height:56px!important;padding:8px 10px!important;border:0!important;border-radius:17px!important;background:#f5f5f7!important;box-shadow:none!important;
}
body.vano-map-surface .planner-preset-icon{background:#fff!important;color:var(--v101-accent)!important;box-shadow:0 1px 4px rgba(0,0,0,.05)!important}
body.vano-map-surface .nearby-service{background:#f5f5f7!important;border:0!important;border-radius:17px!important}
body.vano-map-surface .nearby-service-icon{background:#fff!important;color:var(--v101-accent)!important}
body.vano-map-surface .planner-tip{background:#FFF4EC!important;color:#706861!important}
body.vano-map-surface .search-results{
  border:1px solid var(--v101-line)!important;border-radius:20px!important;background:#fff!important;
  box-shadow:0 18px 40px rgba(18,22,33,.14)!important;overflow:hidden!important;
}

/* Recenter follows the compact sheet rather than floating high in the map. */
body.vano-map-surface:not(.body-nav) .floating-locate{
  display:grid!important;place-items:center!important;width:46px!important;height:46px!important;
  right:max(14px,calc(env(safe-area-inset-right) + 12px))!important;
  bottom:calc(82px + max(24px,env(safe-area-inset-bottom)))!important;
  border:1px solid var(--v101-line)!important;border-radius:16px!important;background:var(--v101-surface)!important;
  color:var(--v101-accent)!important;box-shadow:var(--v101-shadow-soft)!important;
  transition:transform .14s ease!important;
}
body.vano-map-surface:not(.body-nav) .floating-locate:active{transform:scale(.94)!important}

/* Route preview remains rich enough for choice, but uses one clear hierarchy. */
body.vano-map-surface #routeState .route-head h2{font-size:21px!important;letter-spacing:-.55px!important;color:var(--v101-ink)!important}
body.vano-map-surface #routeState .route-head p{color:var(--v101-copy)!important}
body.vano-map-surface #routeState .route-time span{color:var(--v101-ink)!important;font-size:22px!important}
body.vano-map-surface .customize-route-kicker{opacity:.8!important}
body.vano-map-surface .segment,
body.vano-map-surface .travel{background:#f1f1f4!important;border:0!important;border-radius:16px!important;padding:3px!important}
body.vano-map-surface .segment button,
body.vano-map-surface .travel button{border:0!important;box-shadow:none!important}
body.vano-map-surface .segment button.active,
body.vano-map-surface .travel button.active{background:#fff!important;color:var(--v101-ink)!important;box-shadow:0 1px 5px rgba(0,0,0,.08)!important}
body.vano-map-surface .start-trip-cta{
  min-height:58px!important;border-radius:19px!important;background:var(--v101-accent)!important;
  box-shadow:0 10px 24px rgba(217,112,63,.22)!important;
}
body.vano-map-surface .start-trip-cta:active{transform:scale(.985)!important}
body.vano-map-surface .preview-actions .sub-action{border:0!important;border-radius:15px!important;background:#f2f2f5!important;box-shadow:none!important;color:#5f6571!important}

/* =====================================================================
   ACTIVE NAVIGATION — one glance, one action.
   ===================================================================== */
body.vano-map-surface.body-nav .header,
body.vano-map-surface.body-nav .map-tools,
body.vano-map-surface.body-nav .floating-locate,
body.vano-map-surface.body-nav #navDrawerToggle,
body.vano-map-surface.body-nav #navControlDrawer{display:none!important}
body.vano-map-surface.body-nav .map-vignette,
body.vano-map-surface.body-nav .ambient-halo{display:none!important}

body.vano-map-surface.body-nav .nav-maneuver-top{
  top:max(12px,calc(env(safe-area-inset-top) + 8px))!important;
  left:max(12px,calc(env(safe-area-inset-left) + 10px))!important;
  right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;width:auto!important;
  min-height:78px!important;padding:10px 12px!important;border:1px solid var(--v101-line)!important;
  border-radius:25px!important;background:var(--v101-surface)!important;box-shadow:var(--v101-shadow)!important;
  display:grid!important;grid-template-columns:58px minmax(0,1fr)!important;gap:12px!important;align-items:center!important;
}
body.vano-map-surface.body-nav .nav-maneuver-icon{
  width:58px!important;height:58px!important;border-radius:19px!important;background:var(--v101-accent)!important;
  box-shadow:none!important;color:#fff!important;
}
body.vano-map-surface.body-nav .maneuver-glyph{font-size:31px!important;font-weight:850!important}
body.vano-map-surface.body-nav .nav-maneuver-copy b{font-size:20px!important;line-height:1.08!important;letter-spacing:-.5px!important;font-weight:780!important;color:var(--v101-ink)!important}
body.vano-map-surface.body-nav .nav-maneuver-copy span{margin-top:4px!important;font-size:14px!important;font-weight:760!important;color:var(--v101-accent)!important}
body.vano-map-surface.body-nav .nav-street-chip{
  top:calc(max(12px,calc(env(safe-area-inset-top) + 8px)) + 86px)!important;
  left:50%!important;right:auto!important;width:auto!important;max-width:calc(100vw - 48px)!important;
  transform:translateX(-50%)!important;padding:7px 12px!important;border:0!important;border-radius:999px!important;
  background:rgba(26,28,33,.82)!important;color:#fff!important;box-shadow:0 4px 12px rgba(0,0,0,.12)!important;
  font-size:11px!important;font-weight:700!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;
}

/* Bottom arrival bar: visually one solid dock. */
body.vano-map-surface.body-nav #activeNav.nav-panel.nav-minimal{
