  right:max(10px,calc(env(safe-area-inset-right) + 8px))!important;
  bottom:max(10px,calc(env(safe-area-inset-bottom) + 7px))!important;width:auto!important;
  min-height:78px!important;padding:8px 10px!important;border:1px solid var(--v101-line)!important;border-radius:25px!important;
  background:var(--v101-surface)!important;box-shadow:var(--v101-shadow)!important;color:var(--v101-ink)!important;
  overflow:visible!important;
}
body.vano-map-surface.body-nav #activeNav .nav-summary-row{min-height:60px!important;display:grid!important;grid-template-columns:1.05fr 1fr 1fr!important;gap:2px!important;align-items:center!important}
body.vano-map-surface.body-nav #activeNav .nav-summary-item{min-width:0!important;padding:4px 9px!important;position:relative!important;text-align:left!important}
body.vano-map-surface.body-nav #activeNav .nav-summary-item+ .nav-summary-item:before{content:"";position:absolute;left:0;top:10px;bottom:10px;width:1px;background:rgba(22,24,29,.08)}
body.vano-map-surface.body-nav #activeNav .nav-summary-item small{display:block!important;margin-bottom:4px!important;color:#91959e!important;font-size:8px!important;letter-spacing:.07em!important;font-weight:750!important}
body.vano-map-surface.body-nav #activeNav .nav-summary-item strong{display:block!important;color:var(--v101-ink)!important;font-size:18px!important;line-height:1!important;font-weight:800!important;letter-spacing:-.35px!important;white-space:nowrap!important}
body.vano-map-surface.body-nav #activeNav .nav-summary-item:first-child strong{font-size:21px!important;color:var(--v101-accent)!important}
body.vano-map-surface.body-nav #navSearchBtn{display:none!important}

/* Speedometer: numeric, obvious, no tiny technical label. */
body.vano-map-surface.body-nav .floating-speedo{
  left:max(14px,calc(env(safe-area-inset-left) + 12px))!important;right:auto!important;
  bottom:calc(max(10px,calc(env(safe-area-inset-bottom) + 7px)) + 88px)!important;
  width:68px!important;min-width:68px!important;max-width:68px!important;height:52px!important;min-height:52px!important;max-height:52px!important;
  padding:4px 8px!important;border:1px solid var(--v101-line)!important;border-radius:18px!important;
  background:var(--v101-surface)!important;box-shadow:var(--v101-shadow-soft)!important;
  display:flex!important;align-items:baseline!important;justify-content:center!important;gap:3px!important;flex-wrap:nowrap!important;
}
body.vano-map-surface.body-nav .floating-speedo small{display:none!important}
body.vano-map-surface.body-nav .floating-speedo strong{font-size:25px!important;line-height:1!important;font-weight:820!important;letter-spacing:-.7px!important;color:var(--v101-ink)!important}
body.vano-map-surface.body-nav .floating-speedo span{font-size:7px!important;line-height:1!important;color:#8b909a!important;font-weight:700!important;text-transform:uppercase!important}

/* Three controls only: locate, audio, camera. */
body.vano-map-surface.body-nav #navControlStack{
  position:absolute!important;z-index:72!important;left:auto!important;
  right:max(14px,calc(env(safe-area-inset-right) + 12px))!important;
  bottom:calc(max(10px,calc(env(safe-area-inset-bottom) + 7px)) + 88px)!important;
  width:50px!important;min-width:50px!important;max-width:50px!important;
