}
body.vano-map-surface.body-nav #navDrawerRecenter,
body.vano-map-surface.body-nav #soundBtn,
body.vano-map-surface.body-nav #navCameraToggle{
  display:grid!important;place-items:center!important;position:relative!important;inset:auto!important;margin:0!important;padding:0!important;
  width:50px!important;min-width:50px!important;max-width:50px!important;height:50px!important;min-height:50px!important;max-height:50px!important;
  border:1px solid var(--v101-line)!important;border-radius:17px!important;background:var(--v101-surface)!important;color:#5f6570!important;
  box-shadow:var(--v101-shadow-soft)!important;transition:transform .14s ease,background .14s ease,color .14s ease!important;
}
body.vano-map-surface.body-nav #soundBtn.active,
body.vano-map-surface.body-nav #navCameraToggle.active,
