/* Alerts only interrupt the driver when actually important. */
body.vano-map-surface.body-nav .traffic-radar{display:none!important}
body.vano-map-surface.body-nav .traffic-radar.show.severe{
  display:flex!important;left:max(12px,calc(env(safe-area-inset-left) + 10px))!important;
  right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;width:auto!important;
  top:calc(max(12px,calc(env(safe-area-inset-top) + 8px)) + 116px)!important;
  border:0!important;border-radius:19px!important;background:rgba(31,32,37,.92)!important;color:#fff!important;box-shadow:0 8px 26px rgba(0,0,0,.18)!important;
}
