  left:max(12px,calc(env(safe-area-inset-left) + 10px))!important;right:max(12px,calc(env(safe-area-inset-right) + 10px))!important;
  width:auto!important;border:0!important;border-radius:20px!important;background:rgba(31,32,37,.94)!important;color:#fff!important;box-shadow:0 10px 28px rgba(0,0,0,.18)!important;
}
body.vano-map-surface.body-nav .nav-alt-hint .nav-alt-copy small,
body.vano-map-surface.body-nav .nav-alt-hint .nav-alt-copy em{color:rgba(255,255,255,.62)!important}
