@keyframes vano-x-map-fade{from{opacity:.72}to{opacity:1}}
@keyframes vano-x-page-in{
  from{opacity:.001;transform:translateY(7px) scale(.997)}
  to{opacity:1;transform:none}
}

/* One consistent tactile language for interactive elements. */
