/* VANO RESPONSIVE HARDENING V521 */
/* Shared safe-area geometry */
body.vano-map-surface{
  --vano-safe-top:max(8px,env(safe-area-inset-top));
  --vano-safe-right:max(8px,env(safe-area-inset-right));
  --vano-safe-bottom:max(8px,env(safe-area-inset-bottom));
  --vano-safe-left:max(8px,env(safe-area-inset-left));
}
body.vano-map-surface .header{
  top:var(--vano-safe-top)!important;
  right:var(--vano-safe-right)!important;
}
body.vano-map-surface .map-tools{
  top:var(--vano-safe-top)!important;
  right:var(--vano-safe-right)!important;
}
body.vano-map-surface .search-results{
  max-width:calc(var(--vano-vw,100vw) - var(--vano-safe-left) - var(--vano-safe-right) - 12px)!important;
}
body.vano-map-surface :is(#planSheet,#accountDrawer,#prefsDrawer,#safetyDrawer,#quickAlertSheet,#destinationConfirm,#resumeTripCard){
  scrollbar-width:thin;
}

/* Side-rail layouts must scroll instead of clipping on short notebooks/tablets. */
@media(min-width:768px){
  body.vano-map-surface.vano-map-surface:not(.body-nav) #planSheet{
    overflow-x:hidden!important;
    overflow-y:auto!important;
    overscroll-behavior:contain!important;
    scrollbar-gutter:stable;
  }
  body.vano-map-surface #routeState.vano-route-ready{
    min-width:0!important;
  }
  body.vano-map-surface #routeState :is(.route-head,.route-card,.route-deep-grid,.vano-route-more-content){
    min-width:0!important;
  }
  body.vano-map-surface #routeState :is(.vr-copy,.route-option-copy,.route-card-top>div){
    min-width:0!important;
  }
}

/* Phones: explicit navigation HUD geometry independent of legacy rules. */
@media(max-width:767px){
  body.vano-map-surface.body-nav #navManeuverTop{
    left:var(--vano-safe-left)!important;
    right:var(--vano-safe-right)!important;
